// ProvisionerServer is the server API for Provisioner service.
// All implementations must embed UnimplementedProvisionerServer
// for forward compatibility.
//
// Provisioner is implemented by out-of-process provisioning plugins
// (VMs, cPanel, Pterodactyl, ...) speaking gRPC via hashicorp/go-plugin.
// The agent queues provisioning jobs and calls these RPCs as services move
// through their lifecycle.
type ProvisionerServer interface {
	DescribeProvisioner(context.Context, *DescribeProvisionerRequest) (*DescribeProvisionerResponse, error)
	Provision(context.Context, *ProvisionRequest) (*ProvisionResponse, error)
	SuspendService(context.Context, *ServiceActionRequest) (*ServiceActionResponse, error)
	UnsuspendService(context.Context, *ServiceActionRequest) (*ServiceActionResponse, error)
	TerminateService(context.Context, *ServiceActionRequest) (*ServiceActionResponse, error)
	// Renewal capability (additive, gated by supports_renew): the service's
	// paid period moved, and the remote object carries its own paid-through
	// date that has to move with it (a licence expiry, a seat term). Enqueued
	// when a renewal invoice is paid; provisioners that do not declare the flag
	// are never told, because for a machine or a hosting account a renewal
	// changes nothing the remote system needs to hear.
	RenewService(context.Context, *RenewServiceRequest) (*ServiceActionResponse, error)
	// VM capability (additive, gated by supports_vm / supports_console in
	// DescribeProvisionerResponse). Hosts must not call these unless the
	// matching flag is set; plugins without the capability return UNIMPLEMENTED.
	GetVMState(context.Context, *VMRequest) (*VMStateResponse, error)
	VMPowerAction(context.Context, *VMPowerRequest) (*ServiceActionResponse, error)
	GetVMMetrics(context.Context, *VMMetricsRequest) (*VMMetricsResponse, error)
	GetVMConsole(context.Context, *VMRequest) (*VMConsoleResponse, error)
	// Gated by supports_password_reset: set a new root password on the guest
	// and return it. The host shows it to the customer once and never stores,
	// logs or emails it.
	ResetVMPassword(context.Context, *VMRequest) (*VMPasswordResponse, error)
	// Gated by supports_reinstall: wipe the guest and install the image named
	// in config under reinstall_key (the agent writes the customer's pick
	// there). The response may carry a new root password, shown once like a
	// reset; empty means the provider sets none and the reset hands it over.
	ReinstallVM(context.Context, *VMRequest) (*VMPasswordResponse, error)
	// Gated by supports_hostname: rename the server (its hostname on the
	// provider). A declared refusal ("hostname taken") is FAILED_PRECONDITION.
	SetVMHostname(context.Context, *VMHostnameRequest) (*VMEmpty, error)
	// Gated by supports_network: the server's addresses, each with its reverse
	// DNS and whether that record can be edited here.
	GetVMNetwork(context.Context, *VMRequest) (*VMNetworkResponse, error)
	// Gated by supports_reverse_dns (implies supports_network): set the PTR of
	// one single address GetVMNetwork marked editable.
	SetVMReverseDNS(context.Context, *VMReverseDNSRequest) (*VMEmpty, error)
	// Gated by supports_groups: the provider-side groups (SolusVM projects) the
	// server's owner has, which one holds the server, and moving it to another
	// or to a new one.
	GetVMGroups(context.Context, *VMRequest) (*VMGroupsResponse, error)
	SetVMGroup(context.Context, *VMGroupRequest) (*VMGroup, error)
	// Contract 10 (decisions 140 to 143). Every read carries `offered`: false
	// when the product does not open the feature to customers, and the host
	// then shows nothing; an action on a feature not offered is refused
	// (FAILED_PRECONDITION).
	//
	// Gated by supports_private_networks: the private networks (SolusVM VPCs)
	// the server's owner has in the server's location, which this server is
	// on, and creating, joining, leaving and deleting them.
	GetVMPrivateNetworks(context.Context, *VMRequest) (*VMPrivateNetworksResponse, error)
	VMPrivateNetworkAction(context.Context, *VMPrivateNetworkRequest) (*VMEmpty, error)
	// Gated by supports_provider_backups: backups the provider keeps of the
	// server on its own storage (not a RackBill repository), and creating,
	// restoring and deleting them and switching the schedule on or off.
	GetVMBackups(context.Context, *VMRequest) (*VMBackupsResponse, error)
	VMBackupAction(context.Context, *VMBackupActionRequest) (*VMEmpty, error)
	// Gated by supports_boot_modes: what the server boots from next (disk,
	// rescue, an ISO) and the ISOs it may boot. Setting it does not restart
	// the server; the host restarts it when asked.
	GetVMBootMode(context.Context, *VMRequest) (*VMBootModeResponse, error)
	SetVMBootMode(context.Context, *VMBootModeRequest) (*VMEmpty, error)
	// Gated by supports_iso_images (implies supports_boot_modes): add an ISO
	// the provider fetches from a URL, owned by the server's owner, or delete
	// one of the owner's own.
	VMISOAction(context.Context, *VMISOActionRequest) (*VMEmpty, error)
	// Backup capability (additive, gated by supports_backup). The provisioner
	// knows how to snapshot its own guest; the backup repository plugin owns
	// the storage it writes into and hands over a BackupTarget. Restores are
	// gated by supports_restore_backup — a provisioner may be able to produce
	// backups it cannot put back.
	BackupService(context.Context, *BackupServiceRequest) (*BackupOperationResponse, error)
	RestoreService(context.Context, *RestoreServiceRequest) (*BackupOperationResponse, error)
	GetServiceBackupJob(context.Context, *BackupJobRequest) (*BackupOperationResponse, error)
	// Capacity capability (additive, gated by supports_capacity): report what
	// one registered node can hold so the agent's inventory allocator can
	// compute stock and choose placements.
	GetNodeCapacity(context.Context, *NodeCapacityRequest) (*NodeCapacityResponse, error)
	// Config-option enumeration (additive, gated per field by
	// ConfigField.dynamic_options): list the valid values for one config field
	// given what the admin has entered so far, so the panel can offer a
	// dropdown instead of a free-text box — and surface bad credentials before
	// anything is saved. Hosts only call this for fields that declared
	// dynamic_options; plugins without the capability return UNIMPLEMENTED.
	ListConfigOptions(context.Context, *ListConfigOptionsRequest) (*ListConfigOptionsResponse, error)
	// Panel access capability (additive, gated by supports_panel_login /
	// supports_panel_usage). For provisioners whose remote system is a
	// customer-facing control panel (web hosting panels, game panels): mint a
	// single-use SSO login URL into it, and report the subscription's current
	// resource usage. Hosts must not call these unless the matching flag is
	// set; plugins without the capability return UNIMPLEMENTED.
	GetPanelLogin(context.Context, *PanelLoginRequest) (*PanelLoginResponse, error)
	GetPanelUsage(context.Context, *PanelUsageRequest) (*PanelUsageResponse, error)
	// Game server capability (additive, gated by supports_game_server, which
	// implies supports_vm — state and power ride the VM RPCs). The remote
	// system is a game panel whose end-user surface the portal reproduces: an
	// interactive console, files, backups, databases, schedules, network
	// allocations, sub-users, startup variables, settings, and the activity
	// log. One reader and one action RPC per sub-resource; a declared refusal
	// by the panel ("backup limit reached") travels as FAILED_PRECONDITION
	// with the panel's own reason, a transport problem as any other code.
	// Hosts must not call these unless the flag is set; plugins without the
	// capability return UNIMPLEMENTED.
	GetGameServer(context.Context, *GameServerRequest) (*GameServerResponse, error)
	GetGameConsole(context.Context, *GameServerRequest) (*GameConsoleResponse, error)
	SendGameCommand(context.Context, *GameCommandRequest) (*GameAck, error)
	ListGameFiles(context.Context, *GameFilesRequest) (*GameFilesResponse, error)
	ReadGameFile(context.Context, *GameFileReadRequest) (*GameFileReadResponse, error)
	WriteGameFile(context.Context, *GameFileWriteRequest) (*GameAck, error)
	GameFileAction(context.Context, *GameFileActionRequest) (*GameFileActionResponse, error)
	ListGameBackups(context.Context, *GameServerRequest) (*GameBackupsResponse, error)
	GameBackupAction(context.Context, *GameBackupActionRequest) (*GameBackupActionResponse, error)
	ListGameDatabases(context.Context, *GameServerRequest) (*GameDatabasesResponse, error)
	GameDatabaseAction(context.Context, *GameDatabaseActionRequest) (*GameDatabaseActionResponse, error)
	ListGameSchedules(context.Context, *GameServerRequest) (*GameSchedulesResponse, error)
	GameScheduleAction(context.Context, *GameScheduleActionRequest) (*GameScheduleActionResponse, error)
	GameTaskAction(context.Context, *GameTaskActionRequest) (*GameTaskActionResponse, error)
	ListGameAllocations(context.Context, *GameServerRequest) (*GameAllocationsResponse, error)
	GameAllocationAction(context.Context, *GameAllocationActionRequest) (*GameAllocationActionResponse, error)
	ListGameUsers(context.Context, *GameServerRequest) (*GameUsersResponse, error)
	GameUserAction(context.Context, *GameUserActionRequest) (*GameUserActionResponse, error)
	GetGameStartup(context.Context, *GameServerRequest) (*GameStartupResponse, error)
	SetGameVariable(context.Context, *GameVariableSetRequest) (*GameVariableSetResponse, error)
	UpdateGameSettings(context.Context, *GameSettingsRequest) (*GameAck, error)
	ListGameActivity(context.Context, *GameActivityRequest) (*GameActivityResponse, error)
	mustEmbedUnimplementedProvisionerServer()
}

